function advisorOrder(advisors) {
  const rank = { memory: 0, rag: 1, tools: 2, audit: 3 };
  return [...advisors].sort((a, b) => rank[a] - rank[b]).join(',');
}
console.log(advisorOrder(['tools', 'memory', 'rag']));
console.log(advisorOrder(['audit', 'tools']));
